    static void visit(int[] a, int i, List<Integer> path, List<List<Integer>> out) {
        if (i == a.length) { out.add(new ArrayList<>(path)); return; }
        path.add(a[i]);
        visit(a, i + 1, path, out);
        path.remove(path.size() - 1);
        visit(a, i + 1, path, out);
    }

