static List<Integer> heap(int[] a) {
        List<Integer> h=new ArrayList<>();
        for(int value:a) {
            h.add(value); int i=h.size()-1;
            while(i>0) {
                int parent=(i-1)/2;
                if(h.get(parent)>=h.get(i)) break;
                Collections.swap(h,parent,i); i=parent;
            }
        }
        return h;
    }

