        for (int[] row : a) if (row.length != cols) throw new IllegalArgumentException("ragged matrix");
        int[][] out = new int[cols][rows];
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) out[c][r] = a[r][c];
        return out;
    }

